    end
  end

  on_linux do
    on_arm do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.1/codesynapse-linux-arm64"
      sha256 "fe7b05f396f00306d9cf91f26b3e0a35c09ba98e9ca63ed00bae19f701ede5a3"
